--   -- no stat type beyond the 3.3.5 enum survived (expect 0 rows):
--   SELECT entry FROM item_template WHERE entry IN (<the entries above>)
--     AND (stat_type1 > 48 OR stat_type2 > 48 OR stat_type3 > 48
